//! Documentation generator for SotF.
//!
//! Reads plugin PARAMS arrays and generates markdown reference pages
//! into `site/src/content/docs/reference/plugins/`.

// r2factor:facade — do not pass this file back into r2factor
// Auto-generated by r2factor. Manual edits will be overwritten on next split.

#[path = "main/find.rs"]
mod find;
#[path = "main/format.rs"]
mod format;
#[path = "main/generate.rs"]
mod generate;
#[path = "main/misc.rs"]
mod misc;
#[path = "main/parse.rs"]
mod parse;
#[path = "main/plugin_entry.rs"]
mod plugin_entry;
#[cfg(test)]
#[path = "main/tests.rs"]
mod tests;
#[path = "main/types.rs"]
mod types;

use find::find_project_root;
use generate::generate_plugin_index;
use generate::generate_plugin_page;
use misc::write_if_changed;
use parse::parse_args;
use plugin_entry::plugin_registry;
use plugin_entry::validate_registry;

fn main() {
    let args = parse_args();
    let root = find_project_root(args.root);
    let docs_dir = root.join("site/src/content/docs");

    if args.check {
        println!("Checking generated plugin reference pages...");
    } else {
        println!("Generating plugin reference pages...");
    }

    let registry = plugin_registry();
    validate_registry(&registry);
    let mut changed = 0usize;

    // Plugin index page
    let index_md = generate_plugin_index(&registry);
    changed += usize::from(write_if_changed(
        &docs_dir.join("reference/plugins/index.md"),
        &index_md,
        args.check,
    ));

    // Individual plugin pages
    for entry in &registry {
        let page_md = generate_plugin_page(entry);
        let filename = format!("{}.md", entry.slug);
        changed += usize::from(write_if_changed(
            &docs_dir.join("reference/plugins").join(&filename),
            &page_md,
            args.check,
        ));
    }

    if args.check && changed > 0 {
        eprintln!("{changed} generated docs files are out of date.");
        std::process::exit(1);
    }

    println!("Done. Generated {} plugin reference pages.", registry.len());
}
